import{G as e,W as t,n,rt as r}from"./chunks/framework.9o07hMZQ.js";var i=JSON.parse(`{"title":"XVoice 语音教程","description":"","frontmatter":{},"headers":[],"relativePath":"tutorial/xvoice.md","filePath":"tutorial/xvoice.md","lastUpdated":0}`),a={name:`tutorial/xvoice.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="xvoice-语音教程" tabindex="-1">XVoice 语音教程 <a class="header-anchor" href="#xvoice-语音教程" aria-label="Permalink to “XVoice 语音教程”">​</a></h1><p>本教程介绍如何使用 XVoice 语音软件进行语音通讯。</p><h2 id="xvoice-是什么" tabindex="-1">XVoice 是什么 <a class="header-anchor" href="#xvoice-是什么" aria-label="Permalink to “XVoice 是什么”">​</a></h2><p>XVoice 是 XFLYSIM 连飞平台的语音通讯软件。在提供管制服务的空域，语音机组需要使用 XVoice 与管制员及其他机组进行语音通讯。</p><h2 id="安装与登录" tabindex="-1">安装与登录 <a class="header-anchor" href="#安装与登录" aria-label="Permalink to “安装与登录”">​</a></h2><ol><li>下载并安装 XVoice 客户端。</li><li>使用连飞网站注册的账号密码登录。</li></ol><h2 id="连接服务器" tabindex="-1">连接服务器 <a class="header-anchor" href="#连接服务器" aria-label="Permalink to “连接服务器”">​</a></h2><ol><li>打开 XVoice，选择 XFLYSIM 服务器并连接。</li><li>连接成功后，确认软件显示已上线状态。</li></ol><h2 id="使用注意事项" tabindex="-1">使用注意事项 <a class="header-anchor" href="#使用注意事项" aria-label="Permalink to “使用注意事项”">​</a></h2><ul><li>语音机组连入管制空域后，听从管制员指挥并保持语音畅通。</li><li>活动期间，活动空域内的所有航空器驾驶员必须具有双向语音通讯能力。</li><li>不方便语音通讯的机组，平台提供英文文字管制服务。</li><li>请文明用语，和谐沟通。不得辱骂机组或管制员，一经发现直接永久停飞处理。</li></ul>`,10)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};